[4, 5, 6], 
[7, 8, 9]]

### Response:
int maxSum = 0;

// traverse elements in upper-left 
// to lower-right diagonal order 
for (int i = 0; i < Matrix.size(); i++ )
{
    int sum = 0; 
    // traverse diagonal element 
    for (int j = 0; (i+j) < Matrix.size() && j < Matrix.size(); j++ )
        sum += Matrix[i+j][j]; 
    // update max sum 
    maxSum = max(maxSum, sum); 
} 

// traverse elements in upper-right 
// to lower-left diagonal order 
for (int i = 1; i < Matrix.size(); i++ ) 
{ 
    int sum = 0; 
    // traverse diagonal element 
    for (int j = 0; (i+j) < Matrix.size() && j < Matrix.size(); j++ ) 
        sum += Matrix[j][i+j]; 
    // update max sum 
    maxSum = max(maxSum, sum); 
}

### Instruction:
Write a Rust program to find the lowest common ancestor in a given tree.

### Response:
fn lowestCommonAncestor(root: &TreeNode, p: &TreeNode, q: &TreeNode) -> i32 {
 if root == nil {
  return -1;
 }

 if root == p || root == q {
  return root.val;
 }

 let left = lowestCommonAncestor(root.left, p, q);
 let right = lowestCommonAncestor(root.right, p, q);

 if left != -1 && right != -1 {
  return root.val;
 }

 return left != -1 ? left : right;
}

### Instruction:
Write a C# program to sort a given array using the Quick Sort algorithm.

### Input:
array = [8, 4, 1, 9, 6]

### Response:
using System;

namespace QuickSortExample
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] array = { 8, 4, 1, 9, 6 };
            int left = 0;
            int right = array.Length - 1;

            quickSort(array, left, right);

            Console.WriteLine("Sorted array is:");
            foreach (int val in array)
            {
                Console.WriteLine(val);
            }

        }

        static void quickSort(int[] array, int left, int right)
        {
            if (left < right)
            {
                int pivotIndex = partition(array, left, right);

                quickSort(array, left, pivotIndex - 1);
                quickSort(array, pivotIndex + 1, right);
            }
        }

        static int partition(int[] array, int left, int right)
        {
            int pivot = array[right];
            int pivotIndex = left;

            for (int i = left; i < right; i++)
            {
                if (array[i] <= pivot)
                {
                    swap(array, i, pivotIndex);
                    pivotIndex++;
                }
            }

            swap(array, right, pivotIndex);

            return pivotIndex;
        }

        static void swap(int[] array, int i, int j)
        {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }
}

### Instruction:
Write a java program to print the frequencies of all characters in a string.

### Input:
string = "mississippi"

### Response:
public class Frequency { 
	static void characterFrequency(String str) 
	{ 
		// size of the string 'str' 
		int n = str.length(); 

		// 'freq[]' implemented as hash table 
		int freq[] = new int[256]; 

		// accumulate freqeuncy of each character 
		// in 'str' 
		for (int i = 0; i < n; i++) 
			freq[str.charAt(i)]++; 

		// traverse 'str' from left to right 
		for (int i = 0; i < n; i++) { 

			// if frequency of character str.charAt(i) 
			// is not equal to 0 
			if (freq[str.charAt(i)] != 0) { 

				// print the character along with its 
				// frequency 
				System.out.print(str.charAt(i)); 
				System.out.print(freq[str.charAt(i)] + " "); 

				// update frequency of str.charAt(i) to 
				// 0 so that the same character is not printed 
				// again 
				freq[str.charAt(i)] = 0; 
			} 
		} 
	} 

	// Driver code 
	public static void main(String args[]) 
	{ 
		String str = "mississippi"; 
		characterFrequency(str); 
	} 
}

