// Function to find the kth smallest element 
int kthSmallestWComp(int arr[], int n, int k) 
{ 
    // Initialize values of left and right 
    int left = -2147483648, right = 2147483647, ans = -1; 
    while (left <= right) 
    { 
        int mid = (left + right) / 2; 
        int countLtEqMid = 0, countGtMid = 0; 

        // Loop to count total less than equal mid 
        for (int i = 0; i < n; i++) 
            if (arr[i] <= mid) 
                countLtEqMid++; 
        // Loop to count total greater than mid 
        for (int i = 0; i < n; i++) 
            if (arr[i] > mid) 
                countGtMid++; 

        if (countLtEqMid < k && k <= (countLtEqMid + countGtMid)) 
        { 
            ans = mid; 
            left = mid + 1; 
        } 
        else if (countLtEqMid >= k) 
            right = mid - 1; 

        else
            left = mid + 1; 
    } 
    return ans; 
}

### Instruction:
How would you implement a Binary Search Tree in Java?

### Response:
public class BinarySearchTree { 

  /* Class containing left, right and root nodes */
  class Node { 
    int key; 
    Node left, right; 

    public Node(int item) {
		key = item; 
		left = right = null; 
	} 
  } 

  // Root of BST 
  Node root; 

  // Constructor 
  BinarySearchTree() {  
	root = null;  
  } 

  // This method mainly calls insertRec() 
  void insert(int key) { 
	 root = insertRec(root, key); 
  } 

  /* A recursive function to insert a new key in BST */
  Node insertRec(Node root, int key) { 

	// When the tree is empty, return a new node 
	if (root == null) { 
		root = new Node(key); 
		return root; 
	}

	// Otherwise, recurr down the tree 
	if (key < root.key) 
		root.left = insertRec(root.left, key); 
	else if (key > root.key) 
		root.right = insertRec(root.right, key);

	// return the root 
	return root; 
  } 

}

