def index(elements, target):
    """This method finds the index of the first occurrence of the target element in the given list.
    If the target element is not found, it returns -1."""

### Solution:


    left = 0
    right = len(elements) - 1

    while left < right:
        mid = (left + right) // 2

        if elements[mid] == target:
            return mid

        if elements[mid] < target:
            left = mid + 1
        else:
            right = mid

    if elements[left] == target:
        return left
